"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import math
from pathlib import Path
import re
import sys

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context,MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels,TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=65536):
    if type(value) is not str or len(value)>maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def pairs(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def compile_document(document):
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if any(c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-' for c in seed):
        raise ValueError('seed')
    definitions = sequence(document['definitions'],8192)
    for row in definitions:
        sequence(row,2)
        if len(row)!=2:
            raise ValueError('definition pair')
        text(row[0],32)
        text(row[1],8192)
    context = Context(definitions,seed)
    timeout = integer(document['timeout_ms'],1,10**9)
    cases = sequence(document['cases'],2000)
    names = set()
    budget = 0
    fields_count = 0
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if not NAME.fullmatch(name) or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],50000)
        budget += len(frames)
        pause_total = 0
        for frame in frames:
            if type(frame) is not dict or type(frame.get('Type')) is not str:
                raise ValueError('frame')
            if frame['Type']=='sleep':
                pause_total += integer(frame.get('Time_to_Stop'))
            if frame['Type']=='headers':
                if frame.get('headers_kv') is not None:
                    value = frame['headers_kv']
                    if type(value) is not dict:
                        raise ValueError('header mapping')
                    fields_count += len(value)
                elif frame.get('data_to_transfered') is not None:
                    value = sequence(frame['data_to_transfered'],128)
                    fields_count += len(value)
        if pause_total+timeout > MAX:
            raise ValueError('time overflow')
        exp = case['expect']
        exact(exp,['method','target','host'])
        for k in exp:
            value = text(exp[k],8192).encode('ascii')
            if not value or not all(33 <= c <= 126 for c in value):
                raise ValueError('expected identity')
        if TOKEN.fullmatch(exp['method'].encode('ascii')) is None:
            raise ValueError('expected method')
    payload = compile_cases(cases,context)
    payload_dict = payload.model_dump()
    actual_test_cases = {}
    for case_name,frames in payload_dict['test_cases'].items():
        clean_frames = []
        for frame in frames:
            if 'headers_kv' in frame:
                del frame['headers_kv']
            clean_frames.append(frame)
        actual_test_cases[case_name] = clean_frames
    records = sequence(document['events'],50000)
    budget += len(records)
    events = []
    for index,record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        keys = ['at','kind'] if kind=='close' else ['at','kind','stream','end',('fields' if kind=='headers' else 'data')]
        exact(record,keys)
        integer(record['at'])
        if kind not in ('close','headers','data'):
            raise ValueError('event kind')
        row = record.copy()
        if kind!='close':
            integer(row['stream'],0,(1 << 32)-1)
            if type(row['end']) is not bool:
                raise ValueError('event end')
        if kind=='headers':
            raw_fields = sequence(row['fields'],128)
            fields_count += len(raw_fields)
            fields = []
            for j,pair in enumerate(raw_fields):
                sequence(pair,2)
                if len(pair)!=2:
                    raise ValueError('event field pair')
                fields.append((context.template(text(pair[0]),f'event/{index}/h/{j}/n'),
                               context.template(text(pair[1]),f'event/{index}/h/{j}/v')))
            row['fields'] = fields
        elif kind=='data':
            row['data'] = context.template(text(row['data']),f'event/{index}/data')
        events.append(row)
    channels = sequence(document['channels'],256)
    channel_names = set()
    compiled_channels = []
    for index,channel in enumerate(channels):
        exact(channel,['name','parts'])
        name = text(channel['name'],32)
        if not NAME.fullmatch(name) or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'],50000)
        budget += len(parts)
        out_parts = []
        for j,part in enumerate(parts):
            exact(part,['case','data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            out_parts.append({'case':owner,'data':context.template(text(part['data']),f'channel/{index}/part/{j}/data')})
        compiled_channels.append({'name':name,'parts':out_parts})
    if budget>50000 or fields_count>32768:
        raise ValueError('combined budget')
    return cases,actual_test_cases,events,compiled_channels,timeout


def run(document):
    cases,actual_test_cases,events,channels,timeout = compile_document(document)
    fuzzer = FuzzExecutor()
    sent = fuzzer.send_payload(actual_test_cases,events,timeout)
    origin = audit_channels(channels,cases,sent)
    return {'cases':sent,'channels':origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(8*1024**2+1)
        if len(raw)>8*1024**2:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'),object_pairs_hook=pairs,
                              parse_constant=bad_constant,parse_float=finite_float)
        result = run(document)
    except (ValueError,TypeError,KeyError,IndexError,UnicodeError,RecursionError):
        result = {'error':'input'}
    encoded=json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded+b'\n')


if __name__=='__main__':main()

"""Public sanity checker: bounded child CLI, no private inputs and no score."""
import json
import math
import os
from pathlib import Path
import selectors
import signal
import stat
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent


class CandidateFailure(Exception):
    pass


class InfrastructureError(Exception):
    pass


def unique_object(items):
    out = {}
    for k, v in items:
        if k in out:
            raise ValueError('duplicate output key')
        out[k] = v
    return out


def invalid_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(token):
    value = float(token)
    if not math.isfinite(value):
        raise ValueError('nonfinite JSON number')
    return value


def parse_output(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=unique_object,
                      parse_constant=invalid_constant, parse_float=finite_float)


def canonical(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False)


def storage_over_budget(scratch):
    total = entries = 0
    stack = [scratch]
    while stack:
        p = stack.pop()
        try:
            s = p.lstat()
            entries += 1
            if stat.S_ISREG(s.st_mode):
                total += max(s.st_size, s.st_blocks*512)
            elif stat.S_ISDIR(s.st_mode):
                with os.scandir(p) as children:
                    stack.extend(Path(e.path) for e in children)
        except FileNotFoundError:
            continue
        if total > 1024**3 or entries > 50000:
            return True
    return False


def invoke(candidate, raw):
    if os.geteuid() == 0:
        raise InfrastructureError('refusing root candidate execution; use the image default user')
    scratch = Path('/workspace/tmp')
    # The public image owns this dedicated directory; the private worker also
    # clears it before invocation. Only remove scratch entries, never submissions.
    import shutil
    for entry in scratch.iterdir():
        if entry.is_dir() and not entry.is_symlink():
            shutil.rmtree(entry)
        else:
            entry.unlink()
    env = {'PATH':'/usr/local/bin:/usr/bin:/bin', 'LANG':'C', 'LC_ALL':'C',
           'HOME':'/workspace', 'TMPDIR':str(scratch), 'PYTHONHASHSEED':'0',
           'PYTHONUNBUFFERED':'1', 'PYTHONDONTWRITEBYTECODE':'1',
           'OPENBLAS_NUM_THREADS':'1', 'OMP_NUM_THREADS':'1', 'MKL_NUM_THREADS':'1'}
    p = None
    sel = selectors.DefaultSelector()
    streams = []
    buffers = [bytearray(), bytearray()]
    limits = [16*1024**2, 1024**2]
    offset = 0
    deadline = time.monotonic()+60
    next_storage = 0
    try:
        previous = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGTERM, signal.SIGINT})
        try:
            p = subprocess.Popen([sys.executable, '-I', '-B', str(HERE/'runner.py'), str(candidate)],
                                 stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                 cwd='/workspace', env=env, close_fds=True)
            streams = [p.stdin, p.stdout, p.stderr]
        finally:
            signal.pthread_sigmask(signal.SIG_SETMASK, previous)
        for stream in streams:
            os.set_blocking(stream.fileno(), False)
        if raw:
            sel.register(p.stdin, selectors.EVENT_WRITE, -1)
        else:
            p.stdin.close()
        sel.register(p.stdout, selectors.EVENT_READ, 0)
        sel.register(p.stderr, selectors.EVENT_READ, 1)
        while sel.get_map():
            now = time.monotonic()
            if now >= deadline:
                raise CandidateFailure('wall timeout')
            if now >= next_storage:
                if storage_over_budget(scratch):
                    raise InfrastructureError('scratch emergency brake; no score')
                next_storage = now+.25
            for key, _ in sel.select(min(.1, deadline-now)):
                stream, kind = key.fileobj, key.data
                if kind == -1:
                    try:
                        n = os.write(stream.fileno(), memoryview(raw)[offset:offset+65536])
                    except BlockingIOError:
                        continue
                    except BrokenPipeError:
                        sel.unregister(stream)
                        stream.close()
                        continue
                    offset += n
                    if offset == len(raw):
                        sel.unregister(stream)
                        stream.close()
                else:
                    try:
                        block = os.read(stream.fileno(), min(65536,limits[kind]-len(buffers[kind])+1))
                    except BlockingIOError:
                        continue
                    if not block:
                        sel.unregister(stream)
                        stream.close()
                    elif len(buffers[kind])+len(block) > limits[kind]:
                        raise CandidateFailure(('stdout','stderr')[kind]+' limit')
                    else:
                        buffers[kind].extend(block)
        try:
            code = p.wait(timeout=max(.001,deadline-time.monotonic()))
        except subprocess.TimeoutExpired:
            raise CandidateFailure('wall timeout') from None
        if code:
            raise CandidateFailure('nonzero exit status')
        try:
            return parse_output(bytes(buffers[0]))
        except (UnicodeError, ValueError, RecursionError):
            raise CandidateFailure('missing or malformed JSON output') from None
    finally:
        # Candidate code starts only after no-fork seccomp is installed.
        if p is not None:
            if p.poll() is None:
                p.kill()
            p.wait(timeout=5)
        sel.close()
        for stream in streams:
            stream.close()


def interrupted(signum, frame):
    signal.signal(signal.SIGTERM, signal.SIG_IGN)
    signal.signal(signal.SIGINT, signal.SIG_IGN)
    raise KeyboardInterrupt()


def main():
    for sig in (signal.SIGTERM, signal.SIGINT):
        signal.signal(sig, interrupted)
    if len(sys.argv) != 2:
        raise SystemExit('usage: python3 check.py /workspace/project')
    candidate = Path(sys.argv[1]).absolute() / 'main.py'
    s = candidate.lstat()
    if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_size > 8*1024*1024:
        raise SystemExit('submission file must be regular, one link, at most 8 MiB')
    fixtures = json.loads((HERE/'examples.json').read_text())
    try:
        for row in fixtures:
            value = invoke(candidate, row['stdin'].encode('utf-8'))
            try:
                actual = canonical(value)
            except (ValueError, RecursionError, OverflowError):
                raise CandidateFailure('malformed JSON output') from None
            if actual != canonical(row['expected']):
                raise CandidateFailure(row['name']+': output differs from public expectation')
    except KeyboardInterrupt:
        print('INTERRUPTED: no result', file=sys.stderr)
        return 130
    except CandidateFailure as e:
        print('FAIL: '+str(e), file=sys.stderr)
        return 1
    except InfrastructureError as e:
        print('INFRASTRUCTURE ERROR: '+str(e), file=sys.stderr)
        return 2
    print('PASS: '+str(len(fixtures))+' public CLI fixtures (no score)')
    return 0


if __name__ == '__main__':
    sys.exit(main())
