    if end <= left:
        return cut(node.left, start, end)
    if start >= left:
        return cut(node.right, start - left, end - left)
    return merge(cut(node.left, start, left), cut(node.right, 0, end - left))


def materialize(node, limit=65536):
    """Expand a bounded rope into bytes."""
    if node is None:
        return b''
    if node.length > limit:
        raise ValueError('bounded materialization')
