"""Helper: run the candidate on a document and show the result."""
import json, subprocess, sys

def run(doc, raw=None):
    if raw is None:
        raw = json.dumps(doc)
    p = subprocess.run([sys.executable, '-B', '/workspace/project/main.py'],
                       input=raw.encode('utf8'), capture_output=True)
    if p.returncode != 0:
        return {'__exit': p.returncode, '__stderr': p.stderr.decode()[:2000]}
    try:
        return json.loads(p.stdout.decode('utf8'))
    except Exception as e:
        return {'__badjson': str(e), '__out': p.stdout[:400].decode('utf8', 'replace')}

def show(label, doc, raw=None):
    out = run(doc, raw)
    print('===', label)
    print(json.dumps(out, indent=1, sort_keys=True))
    return out
